        points: [t("<b>ядро</b> с терминальным тоном — обязательная часть, изменение тона на последнем ударном слоге;", "<b>nucleus</b> with the terminal tone — the obligatory part, a pitch change on the last stressed syllable;"),
          t("<b>хвост</b> — слоги после ядра; ядро и хвост вместе образуют терминальный тон;", "<b>tail</b> — the syllables after the nucleus; nucleus and tail together form the terminal tone;"),
          t("<b>шкала (голова)</b> — от первого ударного слога до ядра; бывает нисходящей, восходящей и ровной;", "<b>head (scale)</b> — from the first stressed syllable up to the nucleus; descending, ascending or level;"),
          t("<b>предшкала</b> — безударные слоги перед шкалой, низкая или высокая.", "<b>pre-head</b> — unstressed syllables before the head, low or high.")],
